// generated by AI (GitHub Copilot, DeepSeek V4 Flash Vision Exp)
// In-memory session state. The decrypted database (and, inside it, the master
// password + salt used to re-encrypt) never leaves this module's memory and is
// never written to browser storage. Only the selected database descriptor (a
// non-secret id/path/label) survives a lock.

import { computed, ref } from 'vue';

import type { PasswordDatabase } from '../format/passwordDatabase';
import type { DatabaseDescriptor } from '../storage/descriptor';

/** Idle time before the session locks itself (default: 5 minutes). */
export const AUTO_LOCK_MS = 5 * 60 * 1000;

const database = ref<PasswordDatabase | null>(null);
const key = ref<string | null>(null);
const selected = ref<DatabaseDescriptor | null>(null);
const active = ref<DatabaseDescriptor | null>(null);
let timer: ReturnType<typeof setTimeout> | null = null;

/** True while a database is unlocked and held in memory. */
export const unlocked = computed(() => database.value !== null);

/** The in-memory (decrypted) database, or null while locked. */
export const currentDatabase = computed(() => database.value);

/** The master password ("key") used to decrypt/encrypt, or null while locked. */
export const currentKey = computed(() => key.value);

/** The database chosen in the list; kept while locked. */
export const selectedDatabase = computed(() => selected.value);

/** The descriptor of the unlocked database, or null while locked. */
export const activeDescriptor = computed(() => active.value);

/** Choose a database (the unlock screen then asks for its master password). */
export function selectDatabase(descriptor: DatabaseDescriptor | null): void {
  selected.value = descriptor;
}

/**
 * Keep the decrypted database, its descriptor and its master key in memory
 * only. Note: JavaScript strings are immutable, so the password cannot be
 * zeroed — only the references are dropped on lock.
 */
export function setDatabase(
  db: PasswordDatabase,
  masterPassword: string,
  descriptor: DatabaseDescriptor,
): void {
  database.value = db;
  key.value = masterPassword;
  active.value = descriptor;
  selected.value = descriptor;
  touch();
}

/** Update the descriptor after a first save created the remote file. */
export function setActiveDescriptor(descriptor: DatabaseDescriptor): void {
  active.value = descriptor;
  if (
    selected.value === null ||
    selected.value.id === '' ||
    selected.value.id === descriptor.id
  ) {
    selected.value = descriptor;
  }
}

/** Reset the auto-lock timer (call on user activity). */
export function touch(): void {
  if (timer !== null) {
    clearTimeout(timer);
  }
  timer = setTimeout(lock, AUTO_LOCK_MS);
}

/** Drop the in-memory database/key and stop the auto-lock timer. */
export function lock(): void {
  database.value = null;
  key.value = null;
  active.value = null;
  if (timer !== null) {
    clearTimeout(timer);
    timer = null;
  }
}
